checks.script:
f="$HOME/informe.txt"
[ -f "$f" ] || falla "Falta ~/informe.txt"
val() { grep -i "^[[:space:]]*$1[[:space:]]*=" "$f" | head -n 1 | cut -d= -f2- | sed 's/^[[:space:]]*//;s/[[:space:]]*$//'; }
top=$(val top); c=$(val commits); prs=$(val prs)
printf '%s' "$top" | grep -qiE '^camila rojas$' || { printf '%s' "$top" | grep -qiE '^valentina' && falla "top: sin unificar identidades gana Valentina; con .mailmap, ¿quién queda primero?"; falla "top= no es la persona con más commits (git shortlog -sn --no-merges HEAD)"; }
[ "$c" = 10 ] || { [ "$c" = 16 ] && falla "commits: ese número incluye los merges; usa --no-merges"; falla "commits= no calza con lo que muestra git shortlog -sn --no-merges HEAD"; }
[ "$prs" = 6 ] || { [ "$prs" = 7 ] && falla "prs: estás contando también el merge de main dentro de una rama; usa --first-parent"; falla "prs= no calza: cuenta los merges de la línea principal (git log --first-parent --merges)"; }
